def switch_to_metric_dimension(apps, schema_editor):
    """
    Switch all charts which have Interest_Type as primary dimension to use
    Metric implicit_dimension instead.
    If a chart with the resulting configuration already exists, the chart
    at hand will be deleted.
    """
    ChartDefinition = apps.get_model("charts", "ChartDefinition")
