    try:
        itdim = Dimension.objects.get(short_name="Interest_Type")
    except Dimension.DoesNotExist:
        return

    # find all charts with Interest_Type as primary dimension
    for chart in ChartDefinition.objects.filter(primary_dimension=itdim):
        if ChartDefinition.objects.filter(
            primary_dimension=None,
            primary_implicit_dimension="metric",
            secondary_dimension=chart.secondary_dimension,
            secondary_implicit_dimension=chart.secondary_implicit_dimension,
        ).exists():
            chart.delete()
        else:
            chart.primary_dimension = None
            chart.primary_implicit_dimension = "metric"
            chart.save()
    # find all charts with Interest_Type as secondary dimension
    for chart in ChartDefinition.objects.filter(secondary_dimension=itdim):
        if ChartDefinition.objects.filter(
            primary_dimension=chart.primary_dimension,
            primary_implicit_dimension=chart.primary_implicit_dimension,
            secondary_dimension=None,
            secondary_implicit_dimension="metric",
        ).exists():
            chart.delete()
        else:
            chart.secondary_dimension = None
            chart.secondary_implicit_dimension = "metric"
            chart.save()


